import { Flex, Callout, Modal, Skeleton } from '@docs-front/ui';
import { Button, Dialog } from '@bichon/ds';
import {
  createFileRoute,
  Navigate,
  useNavigate
} from '@tanstack/react-router';
import { z } from 'zod';
import { useState, useCallback, useEffect, useRef } from 'react';
import { useModal } from '@/hooks/useModal';
import { postVisualSuggestions } from '@/api/products/mutation';
import { StyledFunnelContentWrapper } from '@/routes/_authenticated/f/-route.style';
import { getFileFromIndexedDB } from '@/utils/file/fileStorage';
import {
  StyledPageSubtitle,
  StyledTemplateName,
  StyledFooter,
  StyledButtonWrapper,
  StyledCounter,
  StyledEmptyState,
  StyledErrorState,
  StyledSkeletonRow
} from '@/routes/_authenticated/f/visual-suggestions/-index.style';
import { Plus, ImageIcon, RefreshCw } from 'lucide-react';
import {
  SuggestionsTable,
  type VisualSuggestion
} from '@/routes/_authenticated/f/visual-suggestions/-components/SuggestionsTable';
import {
  readFillFunnelContext,
  readFillVisualSuggestions,
  upsertFillFunnelContext,
  writeFillVisualSuggestions
} from '@/routes/_authenticated/f/-funnelStorage';

export const Route = createFileRoute(
  '/_authenticated/f/visual-suggestions/$productFileId'
)({
  component: RouteComponent,
  validateSearch: z.object({
    fileName: z.string().optional()
  })
});

const MAX_SUGGESTIONS = 10;

type SuggestionsStatus = 'loading' | 'error' | 'empty' | 'success';

function getSavedContext(productFileId: string) {
  return readFillFunnelContext({
    productFileId,
    steps: ['visual-suggestions', 'settings']
  });
}

function RouteComponent() {
  const { productFileId } = Route.useParams();
  const { fileName } = Route.useSearch();
  const templateFileId = productFileId;
  const navigate = useNavigate();
  const modal = useModal();

  const savedContextRef = useRef(getSavedContext(productFileId));
  const restoredSuggestions = useRef(
    readFillVisualSuggestions({
      productFileId,
      steps: ['visual-suggestions', 'settings']
    })
  );

  const [suggestions, setSuggestions] = useState<VisualSuggestion[]>(
    restoredSuggestions.current ?? []
  );
  const [status, setStatus] = useState<SuggestionsStatus>(
    restoredSuggestions.current
      ? restoredSuggestions.current.length > 0
        ? 'success'
        : 'empty'
      : 'empty'
  );
  const [showResetWarning, setShowResetWarning] = useState(false);

  useEffect(() => {
    upsertFillFunnelContext({
      step: 'visual-suggestions',
      productFileId,
      patch: {
        fileName
      }
    });
  }, [fileName, productFileId]);

  const updateSuggestions = useCallback(
    (updater: VisualSuggestion[] | ((prev: VisualSuggestion[]) => VisualSuggestion[])) => {
      setSuggestions((prev) => {
        const next = typeof updater === 'function' ? updater(prev) : updater;
        writeFillVisualSuggestions({
          step: 'visual-suggestions',
          productFileId,
          fileName,
          suggestions: next
        });
        return next;
      });
    },
    [fileName, productFileId]
  );

  const loadSuggestions = useCallback(async () => {
    const ctx = savedContextRef.current;
    setStatus('loading');
    try {
      const referenceFileIds = ctx?.formData?.referenceFileIds ?? [];
      const referenceFiles = (
        await Promise.all(
          referenceFileIds.map((fileId) => getFileFromIndexedDB(fileId))
        )
      ).flatMap((result) => (result ? [result.file] : []));

      const result = await postVisualSuggestions({
        contents: {
          templateFileId,
          userPrompt: ctx?.formData?.resolvedPrompt ?? ctx?.formData?.prompt ?? '',
          productContents: ctx?.formData?.productContents,
          exportProductFileId: ctx?.formData?.exportProductFileId
        },
        referenceFiles: referenceFiles.length > 0 ? referenceFiles : undefined
      });
      const mapped = result.map((item) => ({
        id: crypto.randomUUID(),
        title: item.name,
        prompt: item.info,
        position: item.position,
        genBy: 'ai' as const,
        selected: true
      }));
      updateSuggestions(mapped);
      setStatus(mapped.length === 0 ? 'empty' : 'success');
    } catch {
      setStatus('error');
    }
  }, [templateFileId, updateSuggestions]);

  // loadSuggestions는 수동 재시도용으로만 유지 (자동 호출 없음, upload에서 API 호출 완료 후 진입)
  const selectedCount = suggestions.filter((s) => s.selected).length;

  const resetSuggestionsAndGoBack = useCallback(() => {
    writeFillVisualSuggestions({
      step: 'upload',
      productFileId,
      fileName,
      suggestions: []
    });
    setSuggestions([]);
    setStatus('empty');
    setShowResetWarning(false);
    navigate({
      to: '/f/upload/$productFileId',
      params: { productFileId },
      search: fileName ? { fileName } : undefined
    });
  }, [fileName, navigate, productFileId]);

  const handleBack = useCallback(() => {
    const hasPrompts = suggestions.some(
      (suggestion) => suggestion.prompt.trim() !== ''
    );

    if (hasPrompts) {
      setShowResetWarning(true);
      return;
    }

    resetSuggestionsAndGoBack();
  }, [resetSuggestionsAndGoBack, suggestions]);

  if (!productFileId) {
    return <Navigate to="/f/template" />;
  }

  if (!savedContextRef.current) {
    return <Navigate to="/f/template" />;
  }

  const savedContext = savedContextRef.current;

  const handleToggle = (id: string) => {
    updateSuggestions((prev) =>
      prev.map((s) => {
        if (s.id !== id) return s;
        if (!s.selected && selectedCount >= MAX_SUGGESTIONS) return s;
        return { ...s, selected: !s.selected };
      })
    );
  };

  const handlePromptChange = (id: string, newPrompt: string) => {
    updateSuggestions((prev) =>
      prev.map((s) => (s.id === id ? { ...s, prompt: newPrompt } : s))
    );
  };

  const handleDelete = (id: string) => {
    updateSuggestions((prev) => {
      const next = prev.filter((s) => s.id !== id);
      if (next.length === 0) setStatus('empty');
      return next;
    });
  };

  const handleAdd = () => {
    if (suggestions.length >= MAX_SUGGESTIONS) {
      modal.openModal(({ isOpen, onClose }) => (
        <Modal isOpen={isOpen} onClose={onClose}>
          <Modal.Header title="이미지 항목 추가 불가" />
          <Modal.Body>
            이미지 생성 제안은 최대 {MAX_SUGGESTIONS}개까지 가능합니다.
            기존 항목을 삭제한 후 새로운 항목을 추가해주세요.
          </Modal.Body>
          <Modal.Footer>
            <Modal.ConfirmButton onClick={onClose}>확인</Modal.ConfirmButton>
          </Modal.Footer>
        </Modal>
      ));
      return;
    }

    const newSuggestion: VisualSuggestion = {
      id: crypto.randomUUID(),
      title: '',
      prompt: '',
      position: '',
      genBy: 'human',
      selected: selectedCount < MAX_SUGGESTIONS
    };
    updateSuggestions((prev) => [...prev, newSuggestion]);
    setStatus('success');
  };

  const handleTitleChange = (id: string, newTitle: string) => {
    updateSuggestions((prev) =>
      prev.map((s) => (s.id === id ? { ...s, title: newTitle } : s))
    );
  };

  const handleNext = () => {
    const selectedSuggestions = suggestions.filter((s) => s.selected);
    const hasEmptyField = selectedSuggestions.some(
      (s) => !s.title.trim() || !s.prompt.trim()
    );
    if (hasEmptyField) {
      modal.openModal(({ isOpen, onClose }) => (
        <Modal isOpen={isOpen} onClose={onClose}>
          <Modal.Header title="입력되지 않은 항목이 있습니다" />
          <Modal.Body>
            선택된 이미지의 제목과 생성 프롬프트를 모두 입력해주세요.
          </Modal.Body>
          <Modal.Footer>
            <Modal.ConfirmButton onClick={onClose}>확인</Modal.ConfirmButton>
          </Modal.Footer>
        </Modal>
      ));
      return;
    }

    navigate({
      to: '/f/settings/$productFileId',
      params: { productFileId },
      search: fileName ? { fileName } : undefined
    });
  };

  const displayFileName = fileName ?? savedContext?.fileName ?? '';

  return (
    <Flex
      direction="column"
      width="100%"
      style={{ minHeight: '0px', flex: 1 }}
    >
      <StyledFunnelContentWrapper>
        <Flex direction="column" gap={24} width="100%" alignItems="flex-start">
          {/* Header */}
          <Flex direction="column" gap={8} width="100%" alignItems="flex-start">
            {displayFileName && (
              <StyledTemplateName>
                &apos;{displayFileName}&apos;
              </StyledTemplateName>
            )}
            <StyledPageSubtitle>
              사업계획서 시각 자료(이미지) 구성
            </StyledPageSubtitle>
          </Flex>

          {/* Info Banner + Counter */}
          <Callout $variant="info">
            <span style={{ flex: 1 }}>
              선택하신 양식과 입력하신 프롬프트를 기반으로 필요한 이미지
              리스트를 AI가 추천합니다.
            </span>
            <StyledCounter>
              {selectedCount}/{MAX_SUGGESTIONS}
            </StyledCounter>
          </Callout>

          {/* Main Content */}
          {status === 'loading' && <LoadingState />}
          {status === 'error' && <ErrorState onRetry={loadSuggestions} />}
          {status === 'empty' && <EmptyState onAdd={handleAdd} />}
          {status === 'success' && (
            <SuggestionsTable
              suggestions={suggestions}
              selectedCount={selectedCount}
              maxSuggestions={MAX_SUGGESTIONS}
              onToggle={handleToggle}
              onTitleChange={handleTitleChange}
              onPromptChange={handlePromptChange}
              onDelete={handleDelete}
              onAdd={handleAdd}
            />
          )}
        </Flex>
      </StyledFunnelContentWrapper>

      <StyledFooter>
        <StyledButtonWrapper>
          <Button
            type="button"
            variant="outlined"
            size="large"
            onClick={handleBack}
          >
            이전
          </Button>
          <Button
            type="button"
            variant="filled"
            size="large"
            disabled={status === 'loading'}
            onClick={handleNext}
          >
            다음 단계
          </Button>
        </StyledButtonWrapper>
      </StyledFooter>

      {showResetWarning && (
        <Dialog
          isOpen={showResetWarning}
          onClose={() => setShowResetWarning(false)}
        >
          <Dialog.Content>
            <div>
              <div
                style={{
                  fontSize: 18,
                  fontWeight: 600,
                  letterSpacing: '-0.02em',
                  color: '#25262C',
                  marginBottom: 16
                }}
              >
                이전 단계로 이동하시겠습니까?
              </div>
              <div
                style={{
                  fontSize: 14,
                  color: '#6E7687',
                  letterSpacing: '-0.02em',
                  lineHeight: 1.6
                }}
              >
                이전 단계로 이동하면 입력하신 이미지 프롬프트가 초기화됩니다.
              </div>
            </div>
          </Dialog.Content>
          <Dialog.Footer>
            <div
              style={{
                display: 'flex',
                justifyContent: 'flex-end',
                gap: 8,
                width: '100%'
              }}
            >
              <Button
                variant="outlined"
                size="large"
                onClick={() => setShowResetWarning(false)}
              >
                취소
              </Button>
              <Button
                variant="warning"
                size="large"
                onClick={resetSuggestionsAndGoBack}
              >
                초기화 후 이동
              </Button>
            </div>
          </Dialog.Footer>
        </Dialog>
      )}
    </Flex>
  );
}

function LoadingState() {
  return (
    <Flex direction="column" gap={0} width="100%">
      {Array.from({ length: 4 }).map((_, i) => (
        <StyledSkeletonRow key={i}>
          <Skeleton loading width={20} height={20} />
          <Skeleton loading width="20%" height={20} />
          <Skeleton loading width="70%" height={20} />
        </StyledSkeletonRow>
      ))}
    </Flex>
  );
}

function EmptyState({ onAdd }: { onAdd: () => void }) {
  return (
    <StyledEmptyState>
      <ImageIcon size={48} />
      추천된 시각 자료가 없습니다.
      <Button type="button" variant="outlined" size="medium" onClick={onAdd}>
        <Plus size={16} />
        직접 항목 추가
      </Button>
    </StyledEmptyState>
  );
}

function ErrorState({ onRetry }: { onRetry: () => void }) {
  return (
    <StyledErrorState>
      시각 자료 추천을 불러오는 데 실패했습니다.
      <Button
        type="button"
        variant="outlined"
        size="medium"
        onClick={onRetry}
      >
        <RefreshCw size={16} />
        다시 시도
      </Button>
    </StyledErrorState>
  );
}
